import { useMutation } from '@tanstack/react-query';
import { DepositRequestDTO, exchangeResponseDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useConvertToDepositMutation = (
  options?: MutationOptions<DepositRequestDTO, CBDCAxiosError, exchangeResponseDTO>,
) => {
  const mutation = useMutation<exchangeResponseDTO, CBDCAxiosError, DepositRequestDTO>({
    ...options,
    mutationFn: exchangeApi.convertToDeposit,
  });

  return {
    ...mutation,
  };
};
